package com.araujovito.creditradar.dashboard;
import com.araujovito.creditradar.credit.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/analytics") public class CreditAnalyticsController {
 private final CreditPositionRepository positions; public CreditAnalyticsController(CreditPositionRepository positions){this.positions=positions;}
 @GetMapping("/concentration") public Concentration concentration(@RequestParam String ticker){var rows=positions.findByAssetTickerIgnoreCase(ticker);return new Concentration(sum(rows,CreditPosition::getIssuer),sum(rows,CreditPosition::getEconomicGroup),sum(rows,CreditPosition::getSector),sum(rows,CreditPosition::getIndexer));}
 @GetMapping("/insights") public Insights insights(@RequestParam String ticker){var rows=positions.findByAssetTickerIgnoreCase(ticker).stream().filter(p->p.getReferenceDate().equals(LocalDate.of(2026,7,31))).toList();var total=rows.stream().map(p->p.getAmountMillions()==null?BigDecimal.ZERO:p.getAmountMillions()).reduce(BigDecimal.ZERO,BigDecimal::add);var groups=sum(rows,CreditPosition::getEconomicGroup);var top=groups.entrySet().stream().max(Map.Entry.comparingByValue()).orElse(null);var sectors=sum(rows,CreditPosition::getSector);var topSector=sectors.entrySet().stream().max(Map.Entry.comparingByValue()).orElse(null);return new Insights(rows.size(),total,top==null?null:top.getKey(),top==null?BigDecimal.ZERO:top.getValue(),top==null||total.signum()==0?BigDecimal.ZERO:top.getValue().multiply(BigDecimal.valueOf(100)).divide(total,2,java.math.RoundingMode.HALF_UP),topSector==null?null:topSector.getKey());}
 @GetMapping("/compare") public Comparison compare(@RequestParam String ticker,@RequestParam LocalDate from,@RequestParam LocalDate to){var before=byIssuer(positions.findByAssetTickerIgnoreCaseAndReferenceDate(ticker,from));var after=byIssuer(positions.findByAssetTickerIgnoreCaseAndReferenceDate(ticker,to));if(before.isEmpty()||after.isEmpty())return new Comparison(from,to,false,"Uma das datas não possui posições detalhadas importadas",List.of());var issuers=new TreeSet<String>();issuers.addAll(before.keySet());issuers.addAll(after.keySet());var changes=issuers.stream().map(i->new Change(i,before.getOrDefault(i,BigDecimal.ZERO),after.getOrDefault(i,BigDecimal.ZERO),after.getOrDefault(i,BigDecimal.ZERO).subtract(before.getOrDefault(i,BigDecimal.ZERO)))).toList();return new Comparison(from,to,true,null,changes);}
 private Map<String,BigDecimal> sum(List<CreditPosition> rows,java.util.function.Function<CreditPosition,String> key){var out=new TreeMap<String,BigDecimal>();rows.forEach(p->out.merge(key.apply(p),p.getAmountMillions()==null?BigDecimal.ZERO:p.getAmountMillions(),BigDecimal::add));return out;}
 private Map<String,BigDecimal> byIssuer(List<CreditPosition> rows){return sum(rows,CreditPosition::getIssuer);}
 public record Concentration(Map<String,BigDecimal> byIssuer,Map<String,BigDecimal> byEconomicGroup,Map<String,BigDecimal> bySector,Map<String,BigDecimal> byIndexer){} public record Insights(int importedPositions,BigDecimal importedAmountMillions,String largestEconomicGroup,BigDecimal largestEconomicGroupAmountMillions,BigDecimal largestEconomicGroupPercent,String largestSector){} public record Change(String issuer,BigDecimal before,BigDecimal after,BigDecimal delta){} public record Comparison(LocalDate from,LocalDate to,boolean ready,String reason,List<Change> changes){}
}
